pub const DESCRIPTOR: &str = r#"{"owner":"STUDIO-MODULE-INTEROP_FIG","version":1,"status":{"editable":"NOT_PROVEN","figma_parity":"NOT_PROVEN","basis":"Container and Kiwi facts are observed in three Operator-authored Figma desktop 126.10.7 files (fig-kiwi, version 106; tests/fixtures, provenance.json). The Kiwi census and the typed node tree decode (tests fig_nodes: node counts match the census, named nodes carry the geometry, colour and text of the PNG references); nothing is mapped into the Studio native document, so editable import is NOT_PROVEN. Hostile-container tests use SYNTHETIC fixtures."},"operation":"open_fig(bytes, Limits, CancellationToken) -> FigContainer {packaging, kind, version, source_sha256, parts[name,bytes,sha256], chunks[index,offset,len,sha256], meta keys}; check_version(&FigContainer, &VersionPolicy) -> Ok | UnsupportedVersion{kind,found}; import_fig(bytes, Limits, VersionPolicy, expected_sha256, CancellationToken) -> FigOutcome::Imported(FigImport {container, kind, version, source_sha256, parts_sha256, schema_summary (Kiwi definition names/kinds/fields), census {node_type_histogram, node_count, root_ids as source ids formatted session:local, file_version (Message.fileVersion, field 18, when present), node_field_histogram (NodeChange field name to node count)} or None with a loss entry, loss, editable: NotProven}) | FigOutcome::OpaqueOnly{container, UnsupportedVersion | UnsupportedKind (fig-diff)}; decode_message_tree(&FigImport, Limits, CancellationToken) / decode_kiwi(schema bytes, message bytes, root, Limits, CancellationToken) -> KiwiValue tree decoded against the file's own embedded schema (bounded: max_depth, max_array_len, max_string_bytes, max_tree_values; no partial tree; test fig_nodes::kiwi_tree_hostile_bounds); decode_document(&FigImport, Limits, CancellationToken) / document_from_tree(&KiwiValue, Option<&FigContainer>, Limits, CancellationToken) -> FigDocument {nodes [id, parent, position, children ordered by position, type_name, name, visible, opacity, blend_mode, transform, size, mask, fills/strokes (solid, gradient stops, image hash -> images/<hex> part), stroke weight/align/join, effects, fill/stroke geometry as path commands, prototype interactions (trigger, actions with destination), flow start, payload per kind (canvas, frame/section with corner radii + auto layout fields + component props, rectangle radii, ellipse arc, star/polygon, vector network, boolean op, text characters/font/size/style runs, symbol variant props, instance symbol id + overrides, variable values + single-mode resolved value, variable set modes)], roots, loss [path, code, count, first node], decoded [field path -> count]}: every field present is either decoded or a field_not_decoded loss (test fig_nodes::real_fields_decoded_or_listed_as_loss); decode_path_blob(bytes, Limits) -> path commands; sanitized_summary(&FigImport, SanitizePolicy) -> excluded part names; decode_semantic(&FigContainer) -> Err(EditableDecoderBlocked) (test actual_fig_instance_variable_prototype_edit_reopen); report(...) -> FigReceipt {receipt, editable: NotProven}","operator":{"intent":"Open a local Figma-family file safely, list what it contains as byte-exact parts with sha256, and say plainly that editable import is not available","result":"A preserved container (every ZIP part and canvas chunk byte-exact with sha256), its kind and version, a typed loss list, and editable = NOT_PROVEN","recovery":"zip_invalid / unsafe_entry_name / duplicate_entry / chunk_overflow: the file is damaged or hostile, re-save it from Figma; budget_exceeded: raise the named Limits field only for a trusted file; not_fig: the input is not a .fig container; unsupported_version: the file is kept opaque, its version has not been observed in a real file (observed: fig-kiwi 106); unsupported_kind: a fig-diff file is kept opaque, its layout is not supported; stale_source: re-inspect the current bytes; editable_decoder_blocked: keep the original .fig, SVG/PNG/token export does not satisfy editable import; canceled: nothing was produced"},"model":{"container":"ZIP (canvas.fig, meta.json, thumbnail.png, images/<hash>) or a bare canvas.fig stream; STORE and DEFLATE only; no ZIP64, encryption or multi-disk; names must be relative without .., backslash, drive colon or control characters; exact and case-folded duplicates rejected; local header must match the central directory (encryption flags, method, CRC and sizes; a data descriptor may defer CRC and sizes with all-zero local fields; test unsupported_version_duplicate_key_bomb_cancel); overlapping entry data refused; CRC-32 verified; DEFLATE data must end exactly at the declared compressed size, bytes after the final block are refused (test unsupported_version_duplicate_key_bomb_cancel)","canvas":"8 ASCII prelude bytes (fig-kiwi design: OBSERVED in real files; fig-jam. FigJam and fig-diff: named in the installed editor, layout not observed; fig-deck: UNVERIFIED, community notes only; anything else is Unknown) + u32 LE version (106 in all real files); for fig-kiwi/fig-jam./fig-deck then u32 LE length-prefixed chunks (real files: exactly two); fig-diff and Unknown keep their bytes with no chunk table; a length past the end of the stream is chunk_overflow","versions":"the default VersionPolicy admits nothing; VersionPolicy::observed() admits only OBSERVED_VERSIONS (fig-kiwi 106); callers opt in per (kind, version); fig-diff is never admitted (unsupported_kind); an unsupported version returns the container opaque-preserved and decodes nothing","preservation":"every ZIP part and every canvas chunk is kept byte-exact with its sha256; source_sha256 binds the import to the input bytes (expected_sha256 mismatch = stale_source)","kiwi":"schema = the first of chunks 0 and 1 that inflates as a raw DEFLATE stream, parsed as a Kiwi binary schema (a parse failure or trailing bytes in that chunk is final, no second candidate) (wire format verified against evanw/kiwi js/binary.ts and js/bb.ts; real files: chunk 0 is the schema, chunk 1 the message; the index found is still recorded); message = the next chunk (zstd when it starts 28 B5 2F FD, else raw DEFLATE); the walker is schema driven and reads the root definition named Message, its nodeChanges array, each element guid {sessionID, localID} and type enum (names verified in three real files and the installed editor schema; absent names give a typed loss); source ids are the file values verbatim, not reminted (test fig_container_bounded_identity_loss); DOCUMENT-typed nodes are the roots; the census exists only when the whole message decodes (unknown field id, truncation, trailing bytes, unrecognised compression = soft loss entry with no census; bound hits and cancellation = hard errors); input left after the compressed schema or message stream (raw DEFLATE end, or the first zstd frame; concatenated zstd frames are valid per RFC 8878 s3.1 but only the first is decoded) is a soft loss entry with no census; duplicate field ids in any definition, structs included, are a schema_invalid refusal (test unsupported_version_duplicate_key_bomb_cancel); int64/uint64 varints are only skipped (9-byte rule, UNVERIFIED)","sanitized":"SanitizePolicy::Sanitized excludes thumbnail.png, meta.json and images/*; Preservation excludes nothing; no write path exists in this slice"},"loss":{"kinds":"preserved_opaque (kept byte-exact, not interpreted), unsupported (not mapped to any Studio model)","node_codes":"field_not_decoded, field_type_unexpected, non_finite_value, enum_value_unknown, node_without_guid, node_removed, duplicate_guid, parent_missing, unreachable_node, node_kind_payload_not_decoded, paint_type_unsupported, image_part_missing, blob_unresolvable, blob_index_out_of_range, blob_base_index_unsupported, path_command_unknown, path_blob_truncated, vector_network_truncated, vector_network_counts_exceed_blob, vector_network_vertex_index, vector_network_segment_index, vector_network_trailing_bytes, variable_set_missing, variable_multi_mode_unresolved, variable_alias_unresolved, variable_mode_value_missing, variable_alias_chain_too_long","examples":"semantic_decode_blocked (canvas.fig), meta_json_top_level_keys_only, thumbnail_not_decoded, image_not_decoded, unknown_part_preserved, schema_chunk_summarized, message_chunk_census_only, chunk_not_interpreted; soft decode failures name the cause, for example unknown_field_id, type_out_of_range, message_compression_unrecognized"},"limits":{"max_bytes":134217728,"max_entries":1024,"max_entry_bytes":67108864,"max_inflated_bytes":268435456,"max_ratio":100,"max_chunks":64,"max_meta_bytes":1048576,"max_meta_keys":256,"max_schema_bytes":4194304,"max_message_bytes":268435456,"max_definitions":4096,"max_fields":1024,"max_depth":32,"max_values":67108864,"max_nodes":4000000,"max_tree_values":16777216,"max_array_len":16777216,"max_string_bytes":16777216,"case_seconds":60},"safety":"no file system, network, process or Figma cloud/API/account access exists in this crate; local copies only","cancel":"CancellationToken is checked at entry and per entry and chunk; a canceled call returns canceled and no partial result","diagnostics":"report() emits one Observe terminal outcome: unsupported_version / not_fig -> Failure(Unsupported); editable_decoder_blocked / decoder_unavailable -> Failure(Unavailable); hostile or malformed input -> Failure(Validation); success carries editable NOT_PROVEN in FigReceipt; no ids, part names or text are serialized by this crate","argus":{"inspect":"FigImport.container, loss, census","action":"the same functions with the same cancellation token","capture":"caller captures the source bytes and the Observe frame under a fresh grant"},"next":"map the typed node tree into the Studio native document (folio/vector records) with loss receipts and an edit/reopen round trip; fig-jam./fig-deck/fig-diff fixtures"}"#;
